-- Paper: Hyprland visual layer. Generated by rice-render from palette.toml.
hl.config({
    general = {
        gaps_in = {{ shape.gaps_in }}, gaps_out = {{ shape.gaps_out }}, border_size = {{ shape.border }},
        col = {
            active_border   = "{{ roles.accent | hypr(ff) }}",
            inactive_border = "{{ roles.border | hypr(ff) }}",
        },
    },
    decoration = {
        rounding = {{ shape.window }}, rounding_power = {{ shape.rounding_power }},
        active_opacity = 1.0, inactive_opacity = {{ opacity.inactive }},
        blur   = { enabled = false },
        shadow = { enabled = true, range = 14, render_power = 2, offset = { 0, 4 }, color = "{{ roles.shadow | hypr(33) }}" },
    },
    group = {
        col = { border_active = "{{ roles.accent | hypr(ff) }}", border_inactive = "{{ roles.border | hypr(ff) }}" },
        groupbar = {
            font_family = "{{ fonts.ui }}", text_color = "{{ roles.fg | hypr(ff) }}",
            col = { active = "{{ roles.selection | hypr(ff) }}", inactive = "{{ roles.surface | hypr(ff) }}" },
        },
    },
    animations = { enabled = true },
})

hl.curve("page", { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} }, { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.animation({ leaf = "windows",    enabled = true, speed = {{ motion.open | div(100) }},      bezier = "page", style = "slide" })
hl.animation({ leaf = "fade",       enabled = true, speed = {{ motion.focus | div(100) }},     bezier = "page" })
hl.animation({ leaf = "workspaces", enabled = true, speed = {{ motion.workspace | div(100) }}, bezier = "page", style = "slide" })
hl.animation({ leaf = "borderangle", enabled = false })

hl.window_rule({ name = "paper-opaque",     match = { tag = "opaque" },    opacity = "1.0 override 1.0 override" })
hl.window_rule({ name = "paper-pip",        match = { tag = "pip" },       border_size = 0 })
hl.window_rule({ name = "paper-fullscreen", match = { fullscreen = true }, border_size = 0, rounding = 0 })
hl.window_rule({ name = "paper-game",       match = { tag = "game" },      no_anim = true, no_shadow = true })
